const fs = require('fs');

/**
 * generate_batch4_quiz.js
 * Appends 18 questions each for:
 * 10. eggs
 * 11. vegetables
 * 12. fruits
 * 13. nuts
 * 14. spices_herbs
 * 15. olives
 * 16. oils_vinegars
 * 
 * Resulting in 162 + (7 * 18) = 288 high-level bilingual professional questions!
 */

const questions = JSON.parse(fs.readFileSync('generated_quiz_all.json', 'utf8'));

function addQ(id, cat, qEn, qDe, optsEn, optsDe, correctIdx, expEn, expDe) {
  questions.push({
    id: id,
    category: cat,
    questionEn: qEn,
    questionDe: qDe,
    optionsEn: optsEn,
    optionsDe: optsDe,
    correctIndex: correctIdx,
    explanationEn: expEn,
    explanationDe: expDe,
    qEn: qEn,
    qDe: qDe,
    optEn: optsEn,
    optDe: optsDe,
    correct: correctIdx,
    expEn: expEn,
    expDe: expDe
  });
}

